static void tohex(const uint8_t *b, char *o) { for (int i = 0; i < 32; i++) sprintf(o + 2 * i, "%02x", b[i]); }
int main(void) {
    char hex[80];
    int n = (int)(sizeof VEC / sizeof *VEC);
    for (int i = 0; i < n; i++) {
        uint8_t buf[40]; memset(buf, 0xEE, sizeof buf);
        hmac_sha256(VEC[i].k, VEC[i].kl, VEC[i].m, VEC[i].ml, buf);
        tohex(buf, hex);
        char name[96];
        snprintf(name, sizeof name, "vector %d (key %zu bytes, message %zu bytes)", i, VEC[i].kl, VEC[i].ml);
        CHECK(name, strcmp(hex, VEC[i].hex) == 0, "expected %s, got %s", VEC[i].hex, hex);
        int guard = 1; for (int j = 32; j < 40; j++) if (buf[j] != 0xEE) guard = 0;
        if (!guard) CHECK("writes exactly 32 bytes", 0, "vector %d wrote past the 32-byte tag", i);
    }
    {
        // Accepts only the exact tag.
        int acc = 0, rej = 0, tot = 0;
        for (int i = 0; i < n; i++) {
            uint8_t tag[32]; for (int j = 0; j < 32; j++) { unsigned v; sscanf(VEC[i].hex + 2 * j, "%2x", &v); tag[j] = (uint8_t)v; }
            tot++;
            if (hmac_verify(VEC[i].k, VEC[i].kl, VEC[i].m, VEC[i].ml, tag, 32)) acc++;
            int allrej = 1;
            for (int b = 0; b < 32; b += 7) { uint8_t t2[32]; memcpy(t2, tag, 32); t2[b] ^= 0x01; if (hmac_verify(VEC[i].k, VEC[i].kl, VEC[i].m, VEC[i].ml, t2, 32)) allrej = 0; }
            uint8_t t3[32]; memcpy(t3, tag, 32); t3[31] ^= 0x80;
            if (hmac_verify(VEC[i].k, VEC[i].kl, VEC[i].m, VEC[i].ml, t3, 32)) allrej = 0;
            if (allrej) rej++;
        }
        CHECK("a correct tag is accepted", acc == tot, "%d of %d correct tags were refused", tot - acc, tot);
        CHECK("a tag with one flipped bit is refused", rej == tot, "%d of %d tampered tags were accepted", tot - rej, tot);
    }
    {
        uint8_t tag[32]; for (int j = 0; j < 32; j++) { unsigned v; sscanf(VEC[1].hex + 2 * j, "%2x", &v); tag[j] = (uint8_t)v; }
        uint8_t longer[40]; memcpy(longer, tag, 32); memset(longer + 32, 0, 8);
        CHECK("a truncated tag is refused", !hmac_verify(VEC[1].k, VEC[1].kl, VEC[1].m, VEC[1].ml, tag, 16) && !hmac_verify(VEC[1].k, VEC[1].kl, VEC[1].m, VEC[1].ml, tag, 0), "only a full 32-byte tag may verify");
        CHECK("a tag with extra bytes is refused", !hmac_verify(VEC[1].k, VEC[1].kl, VEC[1].m, VEC[1].ml, longer, 40), "the length must be exactly 32");
        uint8_t m2[28]; memcpy(m2, VEC[1].m, 28); m2[0] ^= 1;
        CHECK("a changed message is refused", !hmac_verify(VEC[1].k, VEC[1].kl, m2, 28, tag, 32), "the tag must depend on the message");
        CHECK("a different key is refused", !hmac_verify((const uint8_t *)"Jefz", 4, VEC[1].m, VEC[1].ml, tag, 32), "the tag must depend on the key");
    }
    return 0;
}
